import re, urllib.request, os, ssl

def run(url=None, pattern=r'["\'`](?:(?:/[A-Za-z0-9_\-./]*)?(?:api|v1|admin|auth|wallet|market|deal|forum|user|upload)[A-Za-z0-9_\-./]*)["\'`]', max_matches=80, **kw):
    ctx = ssl.create_default_context()
    req = urllib.request.Request(url, headers={'User-Agent': 'vf-js-grep/1.0'})
    raw = urllib.request.urlopen(req, timeout=30, context=ctx).read().decode('utf-8', 'replace')
    os.makedirs(os.path.join('missions', '_jsdump'), exist_ok=True)
    safe = re.sub(r'[^a-zA-Z0-9._-]', '_', url.split('//', 1)[1])[:90]
    fn = os.path.join('missions', '_jsdump', safe + '.js')
    with open(fn, 'w', encoding='utf-8') as f:
        f.write(raw)
    hits = []
    for m in re.finditer(pattern, raw):
        s = m.group(0).strip('"\'`')
        if s and s not in hits:
            hits.append(s)
        if len(hits) >= max_matches:
            break
    # also surface fetch( and method:POST snippets
    fetches = re.findall(r'fetch\((.{0,120})', raw)
    posts = re.findall(r'method\s*:\s*["\']POST["\']', raw)
    return "saved=%s size=%d | endpoints=%d | fetch_snippets=%d | post_methods=%d\nENDPOINTS:\n%s\nFETCH SNIPPETS:\n%s" % (
        fn, len(raw), len(hits), len(fetches), len(posts),
        '\n'.join(hits) if hits else '(none)',
        '\n'.join(x.strip()[:120] for x in fetches[:25]) if fetches else '(none)'
    )

